import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class LockerMover {

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static class ParcelCount {
        private int items;

        ParcelCount(int items) {
            this.items = items;
        }

        int getItems() {
            return items;
        }

        void setItems(int items) {
            this.items = items;
        }
    }

    static class Locker {
        private final ReentrantLock lock = new ReentrantLock();
        private final ParcelCount parcelCount;

        Locker(int initialItems) {
            this.parcelCount = new ParcelCount(initialItems);
        }

        ReentrantLock getLock() {
            return lock;
        }

        ParcelCount getParcelCount() {
            return parcelCount;
        }
    }

    private static final Random RANDOM = new Random();
    private static final long FIXED_DELAY_MS = 50L;
    private static final long RANDOM_DELAY_BOUND_MS = 50L;

    private static long fixedDelay() {
        return FIXED_DELAY_MS;
    }

    private static long randomDelay() {
        return RANDOM.nextInt((int) RANDOM_DELAY_BOUND_MS);
    }

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit)
            throws NotEnoughItemsException, InterruptedException {
        long stopTime = System.nanoTime() + unit.toNanos(timeout);
        while (true) {
            if (System.nanoTime() >= stopTime) {
                return false;
            }
            if (source.getLock().tryLock()) {
                try {
                    if (target.getLock().tryLock()) {
                        try {
                            // All reads/writes of the shared ParcelCount fields happen only
                            // while both locker locks are held, giving a clear happens-before
                            // ordering between threads and eliminating the reported race.
                            if (source.getParcelCount().getItems() < quantity) {
                                throw new NotEnoughItemsException("Source locker does not have enough items");
                            }
                            source.getParcelCount().setItems(source.getParcelCount().getItems() - quantity);
                            target.getParcelCount().setItems(target.getParcelCount().getItems() + quantity);
                            return true;
                        } finally {
                            target.getLock().unlock();
                        }
                    }
                } finally {
                    source.getLock().unlock();
                }
            }
            long remaining = stopTime - System.nanoTime();
            if (remaining <= 0) {
                return false;
            }
            long sleepMs = Math.min(fixedDelay() + randomDelay(), TimeUnit.NANOSECONDS.toMillis(remaining));
            if (sleepMs > 0) {
                Thread.sleep(sleepMs);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Locker locker1 = new Locker(10);
        Locker locker2 = new Locker(5);

        Runnable task1 = () -> {
            try {
                boolean moved = move(locker1, locker2, 3, 2, TimeUnit.SECONDS);
                System.out.println("Task1 move result: " + moved);
            } catch (NotEnoughItemsException e) {
                System.out.println("Task1 failed: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable task2 = () -> {
            try {
                boolean moved = move(locker2, locker1, 2, 2, TimeUnit.SECONDS);
                System.out.println("Task2 move result: " + moved);
            } catch (NotEnoughItemsException e) {
                System.out.println("Task2 failed: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Thread t1 = new Thread(task1);
        Thread t2 = new Thread(task2);
        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Locker1 items: " + locker1.getParcelCount().getItems());
        System.out.println("Locker2 items: " + locker2.getParcelCount().getItems());
    }
}

