        gem.setGlowX(glowX);
        gem.setGlowY(glowY);
    }

    private static StarlightMap<String, MutableGem> deepForge(Map<String, MutableGem> source) {
        StarlightMap<String, MutableGem> copy = new StarlightMap<>();
        for (Map.Entry<String, MutableGem> entry : source.entrySet()) {
            copy.put(entry.getKey(), new MutableGem(entry.getValue()));
        }
        return copy;
    }

    public static void main(String[] args) throws InterruptedException {
